		int fontSize = GuiRoot::normalizedFontSize(12);
		float side = rect.size().x * 0.2f;
		Rect numberRect = Rect::fromLowSize(G3D::Vector2(rect.low.x + 2.0f, rect.high.y - 2.0f - side), G3D::Vector2(side, side));

