			adorn->rect2d(rect.toRect2D(), translucentBackdrop());

		if (isEnabled())
		{
			adorn->rect2d(numberRect.toRect2D(), G3D::Color3::gray());
			G3D::Color4 fontColor(G3D::Color3::white());
