		G3D::Vector3 oldTorqueWorld = root->getBranchTorque();

		G3D::Vector3 localZNegAxis = body->getCoordinateFrame().vectorToObjectSpace(cframe.lookVector());

		float desiredTorqueY = -(root->getBranchIBodyV3().y * localZNegAxis.x * kP);

