    0x478240: '?realloc@?$Array@G@G3D@@AAEXH@Z',
    0x4782d0: '??0CoordinateFrame@G3D@@QAE@XZ',
    0x478330: '?inverse@CoordinateFrame@G3D@@QBE?AV12@XZ',
}
for a, sym in EVIDENCE_NAMES.items():
