    0x5fab50: '?append@?$Array@PAVConnector@RBX@@@G3D@@QAEXABQAVConnector@RBX@@@Z',
    0x5fa870: '?resize@?$Array@PAVPoint@RBX@@@G3D@@QAEXH_N@Z',
    0x5fac30: '?append@?$Array@PAVPoint@RBX@@@G3D@@QAEXABQAVPoint@RBX@@@Z',
